/** Cold storage / refrigerated warehouse sector pages: 1 hub + 50 state + 300 city pages.
 * Generated — do not hand-edit. White-hat rule: every page is built from real
 * jurisdiction facts in cold_storage_data.py; the build fails on missing data.
 */
import fs from "node:fs";
import path from "node:path";
import { htmlShell, SITE } from "./shell";

const FOUNDER_LINE = "By Jeremy Mills, CEO & Founder, Apex Grid Engineering — USAF Veteran";

export interface ColdStorageSection { heading: string; body: string; bullets?: string[] }
export interface ColdStorageFaq { question: string; answer: string }
export interface ColdStorageLink { label: string; href: string }
export interface ColdStoragePage {
  title: string; description: string; h1: string; kicker: string; answer: string;
  sections: ColdStorageSection[]; faqs: ColdStorageFaq[]; links: ColdStorageLink[];
}
export interface ColdStorageStatePage extends ColdStoragePage { stateSlug: string }
export interface ColdStorageCityPage extends ColdStoragePage { stateSlug: string; citySlug: string }

export const coldStorageHubUrl = (): string => "/cold-storage-design/";
export const coldStorageStateUrl = (stateSlug: string): string => `/cold-storage-design/${stateSlug}/`;
export const coldStorageCityUrl = (stateSlug: string, citySlug: string): string =>
  `/cold-storage-design/${stateSlug}/${citySlug}/`;

const ces = (s: string): string =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");

function coldStorageBreadcrumb(items: Array<{ name: string; href?: string }>): string {
  return `<nav class="breadcrumb container">${items
    .map((i) => (i.href ? `<a href="${ces(i.href)}">${ces(i.name)}</a>` : ces(i.name)))
    .join("<span>/</span>")}</nav>`;
}

function coldStorageBreadcrumbSchema(items: Array<{ name: string; href?: string }>) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((i, idx) => ({
      "@type": "ListItem",
      position: idx + 1,
      name: i.name,
      ...(i.href ? { item: `${SITE}${i.href}` } : {}),
    })),
  };
}

function coldStorageFaqSchema(faqs: ColdStorageFaq[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.question,
      acceptedAnswer: { "@type": "Answer", text: f.answer },
    })),
  };
}

/** Render one cold storage page to full HTML. crumbs: [hub, state?, city?]. */
export function coldStoragePage(
  page: ColdStoragePage,
  route: string,
  crumbs: Array<{ name: string; href?: string }>,
): string {
  const orgSchema = {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: "Apex Grid Engineering",
    url: SITE,
  };
  const serviceSchema = {
    "@context": "https://schema.org",
    "@type": "Service",
    name: page.h1,
    description: page.description,
    provider: { "@type": "Organization", name: "Apex Grid Engineering", url: SITE },
    areaServed: "United States",
  };
  const body = `
${coldStorageBreadcrumb(crumbs)}
<section class="hero"><div class="container">
  <p class="kicker">${ces(page.kicker)}</p>
  <h1>${ces(page.h1)}</h1>
  <p class="lede">${ces(page.answer)}</p>
  <p class="note">${ces(FOUNDER_LINE)}</p>
</div></section>
${page.sections.map((s) => `<section class="block"><div class="container"><h2>${ces(s.heading)}</h2><div class="prose"><p>${ces(s.body)}</p>${s.bullets ? `<ul class="scope">${s.bullets.map((b) => `<li>${ces(b)}</li>`).join("")}</ul>` : ""}</div></div></section>`).join("\n")}
<section class="block"><div class="container">
  <h2>Related <em>engineering services</em></h2>
  <div class="linkrow">${page.links.map((l) => `<a href="${ces(l.href)}">${ces(l.label)}</a>`).join("")}</div>
</div></section>
<section class="block"><div class="container"><h2>Frequently asked <em>questions</em></h2><div class="faq">${page.faqs.map((f) => `<details><summary>${ces(f.question)}</summary><div class="a">${ces(f.answer)}</div></details>`).join("")}</div></div></section>
<section class="ctaband"><div class="container">
  <h2>Start your cold storage project</h2>
  <p>Send us the site address, temperature zones, target square footage, and schedule. Apex Grid confirms availability, scope, and professional responsibility before work begins.</p>
  <a class="cta" href="/estimate">Start an Engineering Estimate</a>
</div></section>`;
  return htmlShell({
    title: page.title,
    description: page.description,
    canonical: `${SITE}${route}`,
    schemaJson: [orgSchema, serviceSchema, coldStorageFaqSchema(page.faqs), coldStorageBreadcrumbSchema(crumbs)],
    body,
  });
}

/** Write all cold storage HTML pages under publicDir. Returns route paths for the sitemap. */
export function writeColdStoragePages(publicDir: string): string[] {
  const routes: string[] = [];
  const write = (route: string, html: string): void => {
    const dir = path.join(publicDir, route.replace(/^\/|\/$/g, ""));
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, "index.html"), html);
    routes.push(route);
  };
  write(coldStorageHubUrl(), coldStoragePage(COLD_STORAGE_HUB, coldStorageHubUrl(), [
    { name: "Home", href: "/" },
    { name: "Cold Storage Engineering" },
  ]));
  for (const sp of COLD_STORAGE_STATE_PAGES) {
    const route = coldStorageStateUrl(sp.stateSlug);
    write(route, coldStoragePage(sp, route, [
      { name: "Home", href: "/" },
      { name: "Cold Storage Engineering", href: coldStorageHubUrl() },
      { name: sp.h1 },
    ]));
  }
  for (const cp of COLD_STORAGE_CITY_PAGES) {
    const route = coldStorageCityUrl(cp.stateSlug, cp.citySlug);
    const statePage = COLD_STORAGE_STATE_PAGES.find((s) => s.stateSlug === cp.stateSlug);
    write(route, coldStoragePage(cp, route, [
      { name: "Home", href: "/" },
      { name: "Cold Storage Engineering", href: coldStorageHubUrl() },
      ...(statePage ? [{ name: statePage.h1, href: coldStorageStateUrl(cp.stateSlug) }] : []),
      { name: cp.h1 },
    ]));
  }
  return routes;
}

